      tags: ['mk19', 'mk18', 'mk23'],
      stem: '3、王老汉和张老汉是自由市场上仅有的两个出售西红柿的人。西红柿的市场需求函数为Q= 3200 -1600P，Q= Qw+ Qz，Qw和Qz分别为王老汉和张老汉出售的西红柿的数量，两位老汉种植西红柿的边际成本都为 0.5 元。\n1、两位老汉每年春天决定西红柿种植数量，而且都知道西红柿的市场需求情况，也知道上一年对方卖掉多少西红柿。现假定两位老汉都认为对方今年出售的数量将与去年相同。如果张老汉在t-1 年出售的数量为Qz,t-1，而王老汉在t 年春天决定种植Qw,t，那么，他推算的西红柿的市场价格是多少？他的边际收入是多少？\n2、王老汉为了实现利润最大化，在t 年春天应该种植多少西红柿？\n3、王老汉和张老汉的反应函数分别是什么？达到均衡时，王老汉和张老汉的产量分别为多少？双方的利润为多少？市场价格是多少？这样的均衡是什么均衡？\n4、如果张老汉早播种两天，王老汉偷偷得知张老汉当年的产量将为q，王老汉将做出怎样的决策？如果张老汉早已料到王老汉的行为并知道王老汉的决策方法，张老汉将做出怎样的决策？达到均衡时，张老汉和王老汉的产量分别为多少？双方利润各为多少？市场价格是多少？这样的均衡是什么均衡？如果张老汉推迟种植时间，对自己是否有利？\n5、如果两位老汉进行合作，一起决定总产量，然后按边际成本分配各自产量，则市场价格、各自产量、各自利润为多少？这样的均衡是什么均衡？',
