      id: "cv-ec-pd09", origin: 'card', year: 2015, school: "北京大学光华-431 金融学统计 2015 年", no: "未编号", type: "producer", star: 5,
      tags: ["pd09"],
      stem: "（2015 真题）已知生产函数 $f(x_{1},x_{2})=\\min\\{x_{1},\\,x_{2}^{\\alpha}\\}$（$\\alpha>0$）。求规模报酬递增、不变、递减时 $\\alpha$ 的取值范围。",
      answer: "$$f(tx_{1},tx_{2})=\\min\\{tx_{1},\\,t^{\\alpha}x_{2}^{\\alpha}\\},\\qquad tf=\\min\\{tx_{1},\\,tx_{2}^{\\alpha}\\}$$ 比较二者：$\\alpha>1$ 时 $t^{\\alpha}>t$，$f(tx)>tf$，规模报酬递增；$\\alpha=1$ 时 $t^{\\alpha}=t$，规模报酬不变；$0<\\alpha<1$ 时 $t^{\\alpha}<t$，规模报酬递减。",
      src: { card: "pd09", note: "卡片例题（data/econ.js 的 EXAMPLE[\"pd09\"]）来源原文：2015 北大光华 431 真题。PITFALL[pd09] 无条目 → 省略 traps 字段。MNEM[pd09] 无条目 → 省略 hint 字段。" }
