      stem: "某人持有货币 60 元、粮票 30 元。大米 $x_{1}$ 每单位需 2 元货币 + 1 元粮票，油 $x_{2}$ 每单位需 1 元货币 + 1 元粮票，效用函数 $U=10x_{2}+x_{1}x_{2}$。(1) 货币与粮票不可互换时，写出预算约束集并求最优消费组合；(2) 货币与粮票可按 1:1 互换时，求最优消费组合，并说明该人会用货币换多少粮票。",
      answer: "(1) 货币约束 $$2x_{1}+x_{2}\\le60$$，粮票约束 $$x_{1}+x_{2}\\le30$$。因 $x_{1}\\le30$ 时恒有 $30-x_{1}\\le60-2x_{1}$，故粮票约束先达到，$x_{2}=30-x_{1}$。代入 $$U=10(30-x_{1})+x_{1}(30-x_{1})=300+20x_{1}-x_{1}^{2}$$，令 $$\\frac{dU}{dx_{1}}=20-2x_{1}=0\\Rightarrow x_{1}=10,\\ x_{2}=20,\\ U=400$$（货币仅用 40 元，粮票用尽）。(2) 可互换时总资源折合 $$60+30=90$$，有效价格大米 $3$、油 $2$，预算 $$3x_{1}+2x_{2}=90$$。由 $$MRS=\\frac{x_{2}}{x_{1}+10}=\\frac{3}{2}\\Rightarrow x_{2}=\\frac32x_{1}+15$$，代入得 $6x_{1}=60\\Rightarrow x_{1}=10,\\ x_{2}=30$，$U=600$。此时需货币 $20+30=50$、粮票 $10+30=40$，而原持有货币 60、粮票 30，故应把 10 元货币换成 10 元粮票。",
