      stem: "某商品市场需求 $Q^{d}=100-2P$，市场供给 $Q^{s}=20+2P$。(1) 求均衡价格与均衡数量；(2) 若政府对每单位商品征收 4 元从量税（由供给者缴纳），求新的均衡价与数量，并指出税负在买卖双方间的分担；(3) 若改为对生产者每单位补贴 4 元，求新的均衡价与数量。",
