      tags: ["cu29"],
      stem: "消费者效用 $U=XY$，收入 $m=100$，$P_{Y}=1$ 不变，$P_{X}$ 由 2 降至 1。求：(1) 价格下降对 $X$ 的总效应；(2) 按斯勒茨基法分解为替代效应与收入效应。",
      answer: "(1) 马歇尔需求 $$X=\\frac{m}{2P_{X}}$$。$P_{X}=2$ 时 $X_{0}=\\frac{100}{4}=25$；$P_{X}=1$ 时 $X_{1}=\\frac{100}{2}=50$，故总效应 $$=50-25=25$$。(2) 原消费束 $(25,50)$ 在新价格下成本为 $$1\\times25+1\\times50=75$$，为维持原购买力需补偿到 $m'=75$。补偿需求 $$X^{s}=\\frac{75}{2\\times1}=37.5$$，故替代效应 $$=37.5-25=12.5$$，收入效应 $$=50-37.5=12.5$$。验证：总效应 $=12.5+12.5=25$。",
      altAnswer: "💡 巧解（对偶·希克斯分解）：$U=XY$ 的希克斯需求为 $h_X=U^{1/2}\\Big(\\dfrac{P_Y}{P_X}\\Big)^{1/2}$。原效用 $U_0=25\\times50=1250$，在 $P_X=1$ 处 $h_X=\\sqrt{1250}\\approx35.36$。故希克斯替代效应 $=35.36-25=10.36$，收入效应 $=50-35.36=14.64$（总效应仍 $25$）。注意希克斯与斯勒茨基分解数值不同（$10.36/14.64$ vs $12.5/12.5$），做题时看清题目要求哪种分解。",
