      answer: "持有彩票的期望效用 $EU=0.5\\,u(30)+0.5\\,u(20)=0.5\\times900+0.5\\times800=850$；$u''(W)=-2<0$，风险厌恶。(1) 出售价 $p$ 使 $u(20+p)=850$，即 $60(20+p)-(20+p)^{2}=850\\Rightarrow p^{2}-20p+50=0$，取 $p=10-5\\sqrt{2}\\approx2.93$（另一根超出定义域）。确定性等价 $CE=20+p=30-5\\sqrt{2}\\approx22.93$，风险溢价 $E(W)-CE=25-22.93\\approx2.07$。(2) 购买价 $p_{b}$ 使 $0.5\\,u(30-p_{b})+0.5\\,u(20-p_{b})=u(20)=800$。令 $a=20-p_{b}$，得 $a^{2}-50a+550=0$，取 $a=25-5\\sqrt{3}\\approx16.34$，故 $p_{b}=20-a=5\\sqrt{3}-5\\approx3.66$。(3) 一般地 $CE$ 满足 $60CE-CE^{2}=50W_{0}+250-W_{0}^{2}$，两边对 $W_{0}$ 求导得 $\\dfrac{dCE}{dW_{0}}=\\dfrac{50-2W_{0}}{60-2CE}<1$，故 $\\dfrac{dp}{dW_{0}}=\\dfrac{dCE}{dW_{0}}-1<0$：$W_{0}$ 下降时出售价上升（财富越低边际效用越高、绝对风险厌恶 $\\dfrac{2}{60-2W}$ 越大）。",
