      stem: "某山道小贩独家出售一种工艺品，面临市场需求 $P=100-Q$，无固定成本，边际成本 $MC=5$。(1) 求垄断最优产量与定价、利润；(2) 求完全竞争（$P=MC$）下的产量与价格；(3) 计算垄断造成的无谓损失。",
      answer: "(1) $$TR=100Q-Q^{2},\\quad MR=100-2Q$$ 令 $MR=MC$：$$100-2Q=5\\Rightarrow Q=47.5,\\ P=52.5$$ $$\\pi=(52.5-5)\\times47.5=2256.25$$ (2) 竞争下 $$P=MC\\Rightarrow 100-Q=5\\Rightarrow Q=95,\\ P=5$$。(3) $$DWL=\\frac12(52.5-5)(95-47.5)=\\frac12\\times47.5\\times47.5=1128.125$$",
