      answer: "(1) $TR=PQ=12Q^{1/2}$，$MR=6Q^{-1/2}$；$VC=Q^{3/2}$，$MC=\\tfrac32 Q^{1/2}$。$MR=MC$：$$6Q^{-1/2}=\\tfrac32 Q^{1/2}\\Rightarrow Q=4,\\ P=12/\\sqrt4=6$$ $$\\pi=12\\sqrt4-4^{3/2}-5=24-8-5=11$$ (2) 限价 $P=4$ 下厂商按 $MC=P$ 生产：$$\\tfrac32 Q^{1/2}=4\\Rightarrow Q=64/9$$ $$\\pi=4\\cdot\\tfrac{64}{9}-\\left(\\tfrac{64}{9}\\right)^{3/2}-5=\\tfrac{121}{27}\\approx4.48$$ (3) 最高限价取边际成本定价 $P=MC$（需求与 $MC$ 交点处产量最大）：$$12Q^{-1/2}=\\tfrac32 Q^{1/2}\\Rightarrow Q=8,\\ \\bar P=12/\\sqrt8=3\\sqrt2\\approx4.24$$ 此时 $\\pi=8\\sqrt2-5\\approx6.31>0$，厂商仍愿生产且产量达最大。",
      altAnswer: "💡 巧解（恒弹性加成）：$Q=144P^{-2}$ 的需求价格弹性恒为 $|\\varepsilon|=2$，垄断定价直接由加成公式 $$P=\\frac{MC}{1-\\frac{1}{|\\varepsilon|}}=2MC=2\\cdot\\tfrac32 Q^{1/2}=3Q^{1/2}$$ 与反需求 $P=12Q^{-1/2}$ 联立：$$3Q^{1/2}=12Q^{-1/2}\\Rightarrow Q=4,\\ P=6$$ 免去求 $MR$ 的步骤。",
