      tags: ["mk18"],
      stem: "双寡头古诺竞争，市场需求 $P=100-Q$，两厂商边际成本均为 0。(1) 写出厂商 1 的反应函数；(2) 求古诺均衡产量与价格。",
      answer: "(1) 厂商 1 利润 $$\\pi_{1}=(100-q_{1}-q_{2})q_{1}$$，令 $$\\frac{\\partial\\pi_{1}}{\\partial q_{1}}=100-2q_{1}-q_{2}=0\\Rightarrow q_{1}=\\frac{100-q_{2}}{2}$$。(2) 对称均衡 $q_{1}=q_{2}=q$：$$q=\\frac{100-q}{2}\\Rightarrow q=\\frac{100}{3}$$，总产量 $$Q=\\frac{200}{3}$$，价格 $$P=100-\\frac{200}{3}=\\frac{100}{3}$$。",
      altAnswer: "💡 巧解（对称古诺公式）：对称古诺直接套 $$q_1=q_2=\\frac{a-c}{3b}=\\frac{100-0}{3}=\\frac{100}{3},\\qquad Q=\\frac{2(a-c)}{3b}=\\frac{200}{3},\\qquad P=\\frac{a+2c}{3}=\\frac{100}{3}$$ 无需推导反应函数。",
