      answer: "(1) 古诺 $q_1=q_2=\\frac{9-3}{3}=2$，$\\pi_1=\\pi_2=(9-4-3)\\times2=4$。(2) 序贯：投入研发后 $C_1=0$，古诺得 $q_1=\\frac{9-0+3}{3}=4,\\ q_2=\\frac{9-2\\cdot3+0}{3}=1$，$\\pi_1=16-11=5>4$、$\\pi_2=(4-3)\\times1=1$；不投入则回到 (1)。故企业 1 选择投入，SPE：企业 1 研发（$C_1=0$）、$q_1=4,q_2=1$，利润 $(5,1)$。(3) 同时决策下企业 2 观察不到研发、仍按 $q_2=2$ 反应；若企业 1 研发，其最优 $q_1=\\frac{9-2}{2}=3.5$，$\\pi_1=3.5^2-11=1.25<4$，故不研发。纯策略纳什均衡：企业 1 不研发，$q_1=q_2=2$，$\\pi_1=\\pi_2=4$——研发的战略价值依赖于对手可观察（承诺/可置信性）。",
      traps: "古诺需联立双方反应函数，勿把对称性当作单厂商独立最大化",
