      stem: "斯塔克伯格双寡头，市场需求 $P=100-Q$，两厂商边际成本均为 0，厂商 1 为产量领导者。求领导者与追随者的均衡产量。",
      answer: "先求追随者反应函数：$$q_{2}=\\frac{100-q_{1}}{2}$$。领导者利润 $$\\pi_{1}=(100-q_{1}-q_{2})q_{1}=\\Big(100-q_{1}-\\frac{100-q_{1}}{2}\\Big)q_{1}=\\Big(50-\\frac{q_{1}}{2}\\Big)q_{1}$$，令 $$\\frac{d\\pi_{1}}{dq_{1}}=50-q_{1}=0\\Rightarrow q_{1}=50$$，故 $$q_{2}=\\frac{100-50}{2}=25$$。",
