      tags: ["mk11"],
      stem: "某卫星电视公司在两地出售产品：北京需求 $Q_{B}=60-0.25P_{B}$，天津需求 $Q_{T}=100-0.5P_{T}$，总成本 $C(Q)=1000+40Q$，$Q=Q_{B}+Q_{T}$。(1) 求两地分别定价时的最优价格、销量及利润；(2) 求两地统一定价时的价格、销量及利润；(3) 哪种定价厂商利润更大？用消费者剩余判断消费者偏好哪种。",
      answer: "(1) 反需求 $P_{B}=240-4Q_{B},\\ P_{T}=200-2Q_{T}$。由 $MR=MC$：$MR_{B}=240-8Q_{B}=40\\Rightarrow Q_{B}=25,\\ P_{B}=140$；$MR_{T}=200-4Q_{T}=40\\Rightarrow Q_{T}=40,\\ P_{T}=120$。利润 $=140\\times25+120\\times40-(1000+40\\times65)=4700$。(2) 统一定价 $P$：$Q=60-0.25P+100-0.5P=160-0.75P$，即 $P=\\dfrac{640}{3}-\\dfrac{4}{3}Q$，$MR=\\dfrac{640}{3}-\\dfrac{8}{3}Q=40\\Rightarrow Q=65,\\ P=\\dfrac{380}{3}\\approx126.67$，利润 $=\\dfrac{380}{3}\\times65-3600=\\dfrac{13900}{3}\\approx4633.33$。(3) 厂商偏好价格歧视（$4700>4633.33$）。消费者剩余：价格歧视下 $CS=\\dfrac{1}{2}(240-140)\\times25+\\dfrac{1}{2}(200-120)\\times40=2850$；统一定价下 $CS=\\dfrac{14450}{9}+\\dfrac{12100}{9}=2950$。故消费者偏好统一定价（$2950>2850$）。",
