      tags: ["cu21"],
      stem: "（2016 真题）消费者效用 $U=X_{1}^{0.5}X_{2}^{0.5}$，价格 $P_{1}=10,\\ P_{2}=1$，收入 $I=100$。求其间接效用函数及均衡效用。",
      answer: "把马歇尔需求代入效用函数：$$V(P_{1},P_{2},I)=\\left(\\frac{I}{2P_{1}}\\right)^{0.5}\\left(\\frac{I}{2P_{2}}\\right)^{0.5}=\\frac{I}{2\\sqrt{P_{1}P_{2}}}$$ 甲：$$V(10,1,100)=\\frac{100}{2\\sqrt{10}}=5\\sqrt{10}\\approx15.81$$ 间接效用只取决于价格与收入，是价格变动的福利度量基础。",
      src: { card: "cu21", note: "卡片例题（data/econ.js 的 EXAMPLE[\"cu21\"]）来源原文：2016 北大光华 431 真题。PITFALL[cu21] 无条目 → 省略 traps 字段。MNEM[cu21] 无条目 → 省略 hint 字段。" }
