      tags: ["cu25"],
      stem: "（2021 真题）奶茶店做奶茶加椰果（$X_{1}$）与珍珠（$X_{2}$）两种配料，消费者对一杯奶茶有完全替代效用 $U=2X_{1}+3X_{2}$，两种配料对奶茶店的单位成本相同。奶茶店应如何分配椰果与珍珠的比例？",
