      src: { card: "cu25", note: "卡片例题（data/econ.js 的 EXAMPLE[\"cu25\"]）来源原文：2021 北大光华 431 真题。PITFALL[cu25] 无条目 → 省略 traps 字段。MNEM[cu25] 无条目 → 省略 hint 字段。" }
