      tags: ["it01"],
      stem: "（2024 真题）消费者第一期收入 $y_{1}=2$、第二期收入 $y_{2}=1$，可购买利率 $10\\%$ 的无风险国债，效用 $u=\\ln c_{t}$（折现率 1）。(1) 写出两期预算约束（现值形式）；(2) 求最优国债购买量。",
      answer: "(1) 现值形式预算约束 $$c_{1}+\\frac{c_{2}}{1.1}=2+\\frac{1}{1.1}$$ (2) 设买国债 $b$：$c_{1}=2-b$、$c_{2}=1+1.1b$，最大化 $\\ln(2-b)+\\ln(1+1.1b)$，一阶条件 $$-\\frac{1}{2-b}+\\frac{1.1}{1+1.1b}=0\\Rightarrow b=\\frac{6}{11}\\approx0.545$$ 即买约 $0.545$ 单位国债（第一期储蓄）。",
      src: { card: "it01", note: "卡片例题（data/econ.js 的 EXAMPLE[\"it01\"]）来源原文：2024 北大光华 431 真题。PITFALL[it01] 无条目 → 省略 traps 字段。MNEM[it01] 无条目 → 省略 hint 字段。" }
