      stem: "（2019 真题）某人在当期持现金 $x_{0}$，投资项目以概率 $P$ 在下一期带来 $x_{1}$、以 $1-P$ 在再下一期带来 $x_{2}$，市场无风险利率为 $r$。用现值公式写出投资的期望现值，并求风险中性者投资与不投资无差异时的 $P$。",
