      tags: ["it06"],
      stem: "（2023 真题）两期决策：初始财富 $W$，第一期消费 $C_{1}$ 与储蓄 $S$，第二期消费 $C_{2}=\\mu S$（$\\mu>1$ 为确定储蓄收益率），效用 $U=-\\frac{1}{C_{1}}-\\frac{\\beta}{C_{2}}$（$0<\\beta<1$）。求最优储蓄 $S$，并说明 $\\mu$ 上升时储蓄如何变化。",
