      tags: ["mk22"],
      stem: "（2024 真题）4 个同质厂商（边际成本均为 10）合谋追求利润最大化，代表性消费者购买 $x$ 单位的效用为 $20x-5x^{2}$（逆需求 $P=20-10Q$）。求卡特尔的总产量与价格。",
      answer: "卡特尔整体利润 $$\\Pi=(20-10Q)Q-10Q=10Q-10Q^{2}$$ 令 $\\frac{d\\Pi}{dQ}=10-20Q=0\\Rightarrow Q=\\frac12$，价格 $P=20-10\\times\\frac12=15$。卡特尔按整体 $MR=MC$ 定产（成员再按边际成本分配产量），产量低于古诺（$\\frac45$）、价格更高。",
      src: { card: "mk22", note: "卡片例题（data/econ.js 的 EXAMPLE[\"mk22\"]）来源原文：2024 北大光华 431 真题。PITFALL[mk22] 无条目 → 省略 traps 字段。MNEM[mk22] 无条目 → 省略 hint 字段。" }
