      src: { card: "ta01", note: "卡片例题（data/econ.js 的 EXAMPLE[\"ta01\"]）来源原文：2016 北大光华 431 真题。traps 取自 PITFALL[ta01]。MNEM[ta01] 无条目 → 省略 hint 字段。" }
