      src: { card: "ta02", note: "卡片例题（data/econ.js 的 EXAMPLE[\"ta02\"]）来源原文：2015 北大光华 431 真题。traps 取自 PITFALL[ta02]。MNEM[ta02] 无条目 → 省略 hint 字段。" }
