      src: { card: "ta03", note: "卡片例题（data/econ.js 的 EXAMPLE[\"ta03\"]）来源原文：2023 北大光华 431 真题。traps 取自 PITFALL[ta03]。MNEM[ta03] 无条目 → 省略 hint 字段。" }
